import { join } from 'node:path';
import { test, expect, makeIdToken, signedIn } from './fixtures';
import { evaluateResilienceIq } from '../../packages/engine-core/src/accelerators/resilience-iq/evaluate';
import { parseResilienceIqRequest } from '../../packages/engine-core/src/accelerators/resilience-iq/contract';
import { ARCHETYPES } from '../../packages/engine-core/test/resilience-iq-samples';

// Resilience IQ reads its API from cost-iq-runtime-config.js and its question bank from the hosted copy;
// both are generated by the Amplify build, so the tests serve them.
const RESILIENCE_API = 'https://resilience-test.execute-api.ap-south-1.amazonaws.com';
const EVALUATE = '/api/evaluate/resilience-iq';
const ASSESSMENT = '/api/resilience-iq/assessment';
const BANK = join(process.cwd(), 'resilience-iq/knowledge/question-bank.json');

const permitted = (token: string, refreshToken?: string) => ({
  email: 'consultant@ltm.com',
  token,
  refreshToken,
  role: 'advisor_viewer',
  permissions: { take: ['resilience-iq'], view: ['resilience-iq'] }
});

test.describe('Resilience IQ', () => {
  test.beforeEach(async ({ context, world }) => {
    await context.route(/\/cost-iq-runtime-config\.js$/, route => route.fulfill({
      contentType: 'application/javascript',
      body: `window.COST_IQ_API='${RESILIENCE_API}';window.RESILIENCE_IQ_API='${RESILIENCE_API}';`
    }));
    await context.route(/\/resilience-iq\/knowledge\/question-bank\.json$/, route => route.fulfill({ path: BANK, contentType: 'application/json' }));
    // Like the Lambda: the real contract validates and the real engine scores what the page sends.
    world.on('POST', EVALUATE, ({ body }) => {
      const parsed = parseResilienceIqRequest(body);
      if (!parsed.ok) return { status: 400, body: { ok: false, error: parsed.errors[0], details: parsed.errors } };
      return { body: { ok: true, data: evaluateResilienceIq(parsed.value.answers) } };
    });
    world.on('GET', ASSESSMENT, () => ({ body: { ok: true, data: [] } }));
    world.on('POST', ASSESSMENT, ({ body }) => ({ body: { ok: true, data: { ...body.snapshot } } }));
  });

  test('a signed-out user is sent to sign in', async ({ page }) => {
    await page.goto('/resilience-iq');
    await expect(page).toHaveURL(/\/\?require_login=1&redirect=%2Fresilience-iq/);
  });

  test('a user without Resilience IQ access is turned away', async ({ page, context }) => {
    await signedIn(context, { ...permitted(makeIdToken('consultant@ltm.com')), permissions: { take: ['cloud-iq'], view: ['cloud-iq'] } });
    await page.goto('/resilience-iq');
    await expect(page).toHaveURL(/\/$/);
  });

  test('a permitted user sees the assessment setup under the LTM Vantage brand, with no errors', async ({ page, context, world }) => {
    await signedIn(context, permitted(makeIdToken('consultant@ltm.com')));
    await page.goto('/resilience-iq');
    await expect(page.locator('#app')).toContainText('LTM VANTAGE · RESILIENCE IQ');
    await expect(page).toHaveTitle(/LTM Vantage/);
    expect(world.pageErrors).toEqual([]);
    expect(world.missingFiles).toEqual([]);
  });

  test('an expired token is renewed and the evaluation is sent with it and scored by the engine', async ({ page, context, world }) => {
    await signedIn(context, permitted(makeIdToken('consultant@ltm.com', -60), 'refresh-consultant@ltm.com'));
    await page.goto('/resilience-iq');
    await expect(page).toHaveURL(/\/resilience-iq$/);

    const out = await page.evaluate(async (path) => {
      const res = await (window as any).authFetch((window as any).RESILIENCE_IQ_API + path, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ answers: { 'EX-03': 'Unknown', 'EX-04': 'Unknown' } })
      });
      return { status: res.status, body: await res.json() };
    }, EVALUATE);

    expect(world.refreshCount).toBe(1);
    expect(world.calls).toContain(`POST ${EVALUATE} auth=bearer`);
    expect(out.status).toBe(200);
    expect(out.body.data.status).toBe('requirements_incomplete');
    expect(out.body.data.evidenceRequests).toContain('BIA');
  });

  test('the Resilience IQ question bank studio loads and runs (its script had a syntax error)', async ({ page, context, world }) => {
    await signedIn(context, { email: 'admin@ltm.com', token: makeIdToken('admin@ltm.com'), role: 'super_admin', permissions: {} });
    await page.goto('/resilience-iq-question-bank');
    await expect(page.locator('body')).toContainText('EX-01');
    expect(world.pageErrors).toEqual([]);
  });

  test.describe('full assessment through the page', () => {
    const plan = ARCHETYPES['regulated-bank-tested'];
    let evaluations: any[];

    test.beforeEach(async ({ page, context, world }) => {
      evaluations = [];
      world.on('POST', EVALUATE, ({ body }) => {
        evaluations.push(body);
        const parsed = parseResilienceIqRequest(body);
        if (!parsed.ok) return { status: 400, body: { ok: false, error: parsed.errors[0], details: parsed.errors } };
        return { body: { ok: true, data: evaluateResilienceIq(parsed.value.answers) } };
      });
      await signedIn(context, permitted(makeIdToken('consultant@ltm.com')));
      await page.goto('/resilience-iq');
      await page.locator('#assessmentClient').fill('Acme Bank');
      await page.locator('#assessmentSector').fill('Banking');
      await page.locator('#startAssessmentBtn').click();
      await expect(page.getByRole('button', { name: /Next/ })).toBeVisible();
    });

    /** Answers question `id` by clicking, the way a user would. Waits for it first: Next advances only after the save. */
    async function answer(page: any, id: string, value: unknown) {
      await expect.poll(() => page.evaluate('questions[idx].id')).toBe(id);
      const q = await page.evaluate('({ type: questions[idx].type, rows: questions[idx].rows, cols: questions[idx].cols })');
      if (q.type === 'slider') {
        await page.locator('.scale-pick', { hasText: String(value) }).first().click();
      } else if (q.type === 'matrix') {
        const cells = page.locator('.matrix button');
        for (const [row, col] of Object.entries(value as Record<string, string>)) {
          await cells.nth(q.rows.indexOf(row) * q.cols.length + q.cols.indexOf(col)).click();
        }
      } else {
        for (const label of Array.isArray(value) ? value : [value]) {
          await page.locator('.option').filter({ hasText: new RegExp('^' + String(label).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '$') }).click();
        }
      }
    }

    test('20 answers are sent exactly as chosen, pass the contract, and the report renders without gaps', async ({ page, world }) => {
      const ids: string[] = await page.evaluate('questions.map(q => q.id)');
      expect(ids).toEqual(Object.keys(plan));
      for (const id of ids) {
        await answer(page, id, plan[id]);
        await page.getByRole('button', { name: /Next|Run Resilience Assessment/ }).click();
      }
      await expect(page.getByRole('heading', { name: 'Transformation Roadmap' })).toBeVisible({ timeout: 15_000 });

      expect(world.calls).toContain(`POST ${EVALUATE} auth=bearer`);
      const sent = evaluations[evaluations.length - 1];
      expect(sent.answers).toEqual(plan); // nothing defaulted, nothing invented
      expect(parseResilienceIqRequest(sent).ok).toBe(true);

      const text = await page.locator('#app').innerText();
      expect(text).toContain('Acme Bank');
      expect(text).not.toMatch(/\bundefined\b|\bNaN\b|\bnull\b|\[object Object\]|\{"/);
      const expected = evaluateResilienceIq(plan as any);
      expect(text).toContain(String(expected.preferredPattern));
      expect(text).toContain(expected.executiveReport.recommendationSensitivity[0].trigger);
      expect(world.pageErrors).toEqual([]);
      expect(world.missingFiles).toEqual([]);
    });

    test('an untouched recovery-objective slider is not an answer: the user must choose a value', async ({ page }) => {
      await answer(page, 'EX-01', plan['EX-01']);
      await page.getByRole('button', { name: /Next/ }).click();
      await expect.poll(() => page.evaluate('questions[idx].id')).toBe('EX-02');
      await expect(page.locator('#sliderVal')).toHaveText(/Not set/);
      await page.getByRole('button', { name: /Next/ }).click(); // the "please answer" dialog is accepted by the fixture
      expect(await page.evaluate('questions[idx].id')).toBe('EX-02');
      expect(await page.evaluate("answers['EX-02']")).toBeUndefined();
      await answer(page, 'EX-02', '1-4 hours');
      await page.getByRole('button', { name: /Next/ }).click();
      await expect.poll(() => page.evaluate('questions[idx].id')).toBe('EX-03');
    });

    test('if scoring fails, an error is shown and no report or local result appears', async ({ page, world }) => {
      world.on('POST', EVALUATE, () => ({ status: 503, body: { ok: false } }));
      const ids: string[] = await page.evaluate('questions.map(q => q.id)');
      for (const id of ids) {
        await answer(page, id, plan[id]);
        await page.getByRole('button', { name: /Next|Run Resilience Assessment/ }).click();
      }
      await expect(page.getByRole('alert')).toContainText("We couldn't calculate your results");
      await expect(page.getByRole('heading', { name: 'Transformation Roadmap' })).toHaveCount(0);
      expect(await page.evaluate('result')).toBeNull();
    });
  });
});
